configuration.source:
import java.nio.charset.StandardCharsets
File sourceDir = new File(project.basedir, "src/test/java/net/kurobako/cef4j/osr/jfx/compat/javafx") File targetDir = new File(project.build.directory, "generated-test-sources/cef-compat") if (!sourceDir.isDirectory()) { return } if (targetDir.exists()) { targetDir.deleteDir() } targetDir.mkdirs() sourceDir.eachFileRecurse { File sourceFile -> if (!sourceFile.name.endsWith(".java")) { return } String text = sourceFile.getText("UTF-8") text = text.replace("package net.kurobako.cef4j.osr.jfx.compat.javafx;", "package net.kurobako.cef4j.osr.jfx.compat.cef;") text = text.replace("import static net.kurobako.cef4j.osr.jfx.compat.javafx.FxWebViewRuntimeTestSupport.*;", "import static net.kurobako.cef4j.osr.jfx.compat.cef.FxWebViewRuntimeTestSupport.*;") text = text.replace("import javafx.scene.web.WebView;", "import net.kurobako.cef4j.osr.jfx.CefWebView;") text = text.replace("import javafx.scene.web.WebEngine;", "import net.kurobako.cef4j.osr.jfx.CefWebEngine;") text = text.replace("import javafx.scene.web.WebHistory;", "import net.kurobako.cef4j.osr.jfx.CefWebHistory;") text = text.replace("import javafx.scene.web.PopupFeatures;", "import net.kurobako.cef4j.osr.jfx.CefPopupFeatures;") text = text.replace("import javafx.scene.web.PromptData;", "import net.kurobako.cef4j.osr.jfx.CefPromptData;") text = text.replace("import javafx.scene.web.WebErrorEvent;", "import net.kurobako.cef4j.osr.jfx.CefWebErrorEvent;") text = text.replace("import javafx.scene.web.WebEvent;", "import net.kurobako.cef4j.osr.jfx.CefWebEvent;") text = text.replaceAll("\bWebView\b", "CefWebView") text = text.replaceAll("\bWebEngine\b", "CefWebEngine") text = text.replaceAll("\bWebHistory\b", "CefWebHistory") text = text.replaceAll("\bPopupFeatures\b", "CefPopupFeatures") text = text.replaceAll("\bPromptData\b", "CefPromptData") text = text.replaceAll("\bWebErrorEvent\b", "CefWebErrorEvent") text = text.replaceAll("\bWebEvent\b", "CefWebEvent")
// On macOS with -XstartOnFirstThread, cef_initialize() must run BEFORE Platform.startup() // takes over the AppKit main thread. CefWebView.initialise() cannot be called yet because // CefWebView extends Node and loading it triggers Node.<clinit> which requires the toolkit. // So preStartup() pre-initialises CEF directly; postStartup() then calls CefWebView.initialise() // which detects CEF is already running and just records the setup state. text = text.replace( ' static void preStartup() {
 // no-op; replaced in the generated CEF variant to pre-initialise CEF on macOS
 }', ' static void preStartup() {
' + ' if (OS.isMacOS()) {
' + ' net.kurobako.cef4j.SystemBootstrap.load();
' + ' net.kurobako.cef4j.gen.CefSettings.Mutable s = new net.kurobako.cef4j.gen.CefSettings.Mutable();
' + ' s.windowlessRenderingEnabled = 1;
' + ' s.externalMessagePump = 1;
' + ' s.multiThreadedMessageLoop = 0;
' + ' s.noSandbox = 1;
' + ' java.nio.file.Path cacheDir = java.nio.file.Path.of(System.getProperty("java.io.tmpdir"), "cef4j-jfx-cache");
' + ' try { java.nio.file.Files.createDirectories(cacheDir); } catch (java.io.IOException ignored) {}
' + ' s.cachePath = cacheDir.toAbsolutePath().toString();
' + ' Cef.INSTANCE.initialise(s, java.util.List.of("--disable-popup-blocking", "--no-sandbox"));
' + ' }
' + ' }') text = text.replace( ' static void postStartup() {
 // no-op; replaced in the generated CEF variant to initialise CefWebView
 }', ' static void postStartup() {
 CefWebView.initialise();
 }')
String relative = sourceDir.toPath().relativize(sourceFile.toPath()).toString() File outFile = new File(targetDir, "net/kurobako/cef4j/osr/jfx/compat/cef/" + relative) outFile.parentFile.mkdirs() outFile.write(text, "UTF-8") }
